const out = [];
function walk(n) {
  if (n.type === 'COMPONENT' || n.type === 'COMPONENT_SET') {
    out.push({ name: n.name, type: n.type, id: n.id, key: n.key });
  }
  if ('children' in n) {
    for (const c of n.children) walk(c);
  }
}
