  function findFrame(name){ const f=page.findOne(n=>n.name===name && (n.type==='FRAME')); return f; }

  // Fix 02 tab bar overlap: move Lihat Semua up a bit
  const f2 = findFrame('02_Trending');
  const lihat = f2.findOne(n=>n.name==='liatsemua'); if(lihat) lihat.y = 1080;
  const chev = f2.findOne(n=>n.name==='Icon_Chevron_Right'); if(chev && Math.abs(chev.y-1089)<2) chev.y = 1081;

  // hotspot helper: creates an invisible rect on screen at x,y,w,h with reaction to destId
  function hot(screen, x, y, w, h, destId){
    const r = figma.createRectangle();
    r.resize(w,h); r.x=x; r.y=y;
    r.fills=[{type:'SOLID',color:{r:1,g:0,b:0},opacity:0.001}];
    r.name='hotspot';
    screen.appendChild(r);
    r.reactions = [{
      trigger: { type:'ON_CLICK' },
      action: { type:'NODE', destinationId: destId, navigation: 'NAVIGATE', transition: { type: 'DISSOLVE', duration: 200, easing: 'EASE_OUT' } }
    }];
  }

  // 01_Aktivitas
  const d1 = { '01_Aktivitas':'21:66', '02_Trending':'22:124', '04_Top_Up_Metode':'23:223' };
  const f1 = findFrame('01_Aktivitas');
