    hot(f1, 75,870,75,78, d1['02_Trending']);   // Trending tab
    hot(f1, 150,870,75,78, d1['04_Top_Up_Metode']); // Top Up tab
  }

  // 02_Trending
  const d2 = { '01_Aktivitas':'21:66','03_Detail_Saham':'26:414','04_Top_Up_Metode':'23:223' };
